from pathlib import Path
import base64
import sys

if len(sys.argv) != 2:
    raise SystemExit("Usage: apply_psp_live_flogb_v0_5_7c4r1.py <ppsspp_repo>")

repo = Path(sys.argv[1]).resolve()

def require(rel):
    p = repo / rel
    if not p.exists():
        raise SystemExit(f"Missing expected path: {rel}")
    return p

def replace_between(text, start, end, replacement, label):
    a = text.find(start)
    if a < 0:
        raise SystemExit(f"{label}: start marker missing")
    b = text.find(end, a + len(start))
    if b < 0:
        raise SystemExit(f"{label}: end marker missing")
    return text[:a] + replacement + "\n\n" + text[b:]

debug = require("UI/DebugOverlay.cpp")
info = require("PSP_LIVE_FLOGB_BUILD_INFO.txt")
s = debug.read_text(encoding="utf-8")

# R1 intentionally patches directly on top of the proven V0.5.7C3 renderer.
for marker in (
    "g_scbdWinnerFinalTextures[4]",
    "SCBD_RUNTIME_DIAGNOSTIC_VISIBLE = false",
    "SCBDVirtualInput::Process();",
    "DrawSCBDMatchTop5HUD",
):
    if marker not in s:
        raise SystemExit(f"V0.5.7C4R1 prerequisite missing: {marker}")

asset_dir = repo / "assets/scbd/winner_asset_v057c4r1"
asset_dir.mkdir(parents=True, exist_ok=True)

ASSETS = {'victory_final.png': '', 'pick_final.png': '', 'locked_final.png': '', 'timeout_final.png': '', 'splash_10_kratos.png': ''}
for name, encoded in ASSETS.items():
    p = asset_dir / name
    p.write_bytes(base64.b64decode(encoded))
    if p.stat().st_size < 50000:
        raise SystemExit(f"V0.5.7C4R1 asset unexpectedly small: {name}")

renderer = base64.b64decode('').decode("utf-8")
s = replace_between(
    s,
    "static Draw::Texture *g_scbdWinnerFinalTextures[4]",
    "static void DrawSCBDBoneMapper(",
    renderer,
    "replace V0.5.7C3 winner renderer with V0.5.7C4R1",
)
debug.write_text(s, encoding="utf-8")

final = debug.read_text(encoding="utf-8")
required = (
    "WINNER FINAL V0.5.7C4R1",
    "winner_asset_v057c4r1/victory_final.png",
    "winner_asset_v057c4r1/pick_final.png",
    "winner_asset_v057c4r1/locked_final.png",
    "winner_asset_v057c4r1/timeout_final.png",
    "winner_asset_v057c4r1/splash_10_kratos.png",
    "visible slot number makes /pick 1-28 unambiguous",
)
for marker in required:
    if marker not in final:
        raise SystemExit(f"V0.5.7C4R1 generated source missing: {marker}")

with info.open("a", encoding="utf-8") as f:
    f.write(
        "\nPSP Live FloGB V0.5.7C4R1 Clean Rebuild\n"
        "Fresh workflow/patch filenames; skips broken C4 chain\n"
        "Fixed stale preflight expectations and undefined roster S() scale\n"
        "Avatar/text/timer/slot-number/Locked-In polish retained\n"
    )

print("PSP Live FloGB V0.5.7C4R1 patch applied successfully.")
